content.css:
/* Theme tokens. visual.ts pushes the resolved palette onto the root as CSS
   custom properties (src/theme.ts); the fallbacks below are the light preset,
   so a render with no tokens set matches the pre-theme visual.
   Brand accent stays fixed - it is suite chrome, not a themeable surface. */
.bfusion-root {
  width: 100%;
  height: 100%;
  overflow: auto;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  background-color: var(--bf-bg, #FFFFFF);
  position: relative;
}
.bfusion-root *,
.bfusion-root *:before,
.bfusion-root *:after {
  box-sizing: border-box;
}
.bfusion-chart-wrap {
  width: 100%;
  height: 100%;
  display: block;
  background: var(--bf-bg, #FFFFFF);
}
.bfusion-landing-wrap {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  background-color: var(--bf-bg, #FFFFFF);
}
.bfusion-landing {
  display: flex;
  flex-direction: column;
  align-items: center;
  max-width: 420px;
  padding: 20px;
  box-sizing: border-box;
  text-align: center;
}
.bfusion-landing__logo-container {
  width: 130px;
  height: 84px;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #FF5500;
  border-radius: 12px;
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.08);
  margin-bottom: 24px;
  overflow: hidden;
}
.bfusion-landing__logo {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.bfusion-landing__text-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
}
.bfusion-landing__title {
  font-size: 15px;
  font-weight: 600;
  color: var(--bf-text, #242424);
  margin: 0 0 14px 0;
  padding: 0;
  line-height: 1.2;
}
.bfusion-landing__description {
  font-size: 11.5px;
  font-weight: 400;
  color: var(--bf-muted, #667079);
  margin: 0;
  padding: 0;
  line-height: 1.5;
}
.bfusion-landing__description strong {
  font-weight: 600;
  color: var(--bf-text, #242424);
}
.bfusion-landing__separator {
  width: 60%;
  height: 1px;
  background-color: var(--bf-rule, #E5E7EB);
  margin: 20px 0;
}
.bfusion-landing__metadata {
  font-size: 10.5px;
  color: var(--bf-muted, #667079);
  margin-bottom: 4px;
  font-weight: 400;
  line-height: 1.4;
}
.bfusion-landing__metadata strong {
  font-weight: 600;
  color: var(--bf-muted, #667079);
}
/* FTE Decision Board specific */
.fte-board {
  scrollbar-width: thin;
  scrollbar-color: var(--bf-rule, #E5E7EB) transparent;
}
.fte-board::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
.fte-board::-webkit-scrollbar-thumb {
  background: var(--bf-rule, #E5E7EB);
  border-radius: 3px;
}
.fte-kpi-bar {
  animation: fte-fadein 0.4s ease;
}
@keyframes fte-fadein {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
/* ========================================================================== */
/* Suite-shared chrome                                                         */
/*                                                                             */
/* The control strip, the segmented pickers, the insights rail and the tooltip */
/* card are deliberately the SAME class names and the same values as           */
/* bfusion-CapacityPlanning (and bfusion-ResourceHeatmap's rh- equivalents).    */
/* The three visuals sit on one report page and have to read as one product.   */
/* ========================================================================== */
.bfusion-controls {
  display: flex;
  align-items: center;
  gap: 8px 18px;
  flex-wrap: wrap;
  padding: 6px 12px;
  box-sizing: border-box;
  background: var(--bf-tile, #FFFFFF);
  border-bottom: 1px solid var(--bf-rule, #E5E7EB);
  user-select: none;
}
.bfusion-controls__label {
  font-size: 9.5px;
  font-weight: 650;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--bf-muted, #667079);
  white-space: nowrap;
}
.bfusion-controls__note {
  font-size: 10px;
  color: #d97706;
}
/* Segmented picker (Analysis, and Week / Month / Quarter / Year). */
.bfusion-seg {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 2px;
  background: var(--bf-surface-alt, #F4F5F7);
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-radius: 999px;
}
.bfusion-seg--disabled {
  opacity: 0.5;
}
.bfusion-seg__btn {
  appearance: none;
  border: none;
  background: transparent;
  font-family: inherit;
  font-size: 10.5px;
  font-weight: 550;
  color: var(--bf-muted, #667079);
  padding: 3px 11px;
  border-radius: 999px;
  cursor: pointer;
  white-space: nowrap;
  line-height: 1.5;
  transition: background 0.15s ease, color 0.15s ease, box-shadow 0.15s ease;
}
.bfusion-seg__btn:hover:not(:disabled) {
  color: var(--bf-text, #242424);
  background: color-mix(in srgb, var(--bf-tile, #fff) 75%, transparent);
}
.bfusion-seg__btn--active {
  background: var(--bf-tile, #FFFFFF);
  color: var(--bf-text, #242424);
  font-weight: 650;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.08);
}
.bfusion-seg__btn:disabled {
  color: #c4c8ce;
  cursor: not-allowed;
  background: transparent;
}
.bfusion-seg__btn:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 1px;
}
/* Vertical INSIGHTS rail — the panel's only open/close control. */
.bfusion-insight-strip {
  background: var(--bf-surface-alt, #F4F5F7);
  border-left: 1px solid var(--bf-rule, #E5E7EB);
  color: var(--bf-muted, #667079);
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  user-select: none;
  transition: background 0.15s ease, color 0.15s ease;
  flex: 0 0 26px;
  width: 26px;
}
.bfusion-insight-strip__arrow {
  font-size: 10px;
  color: #D97B29;
  line-height: 1;
}
.bfusion-insight-strip__label {
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  letter-spacing: 0.18em;
  font-size: 9px;
  font-weight: 650;
  color: var(--bf-muted, #667079);
  text-transform: uppercase;
}
.bfusion-insight-strip:hover,
.bfusion-insight-strip:focus {
  background: var(--bf-rule, #E5E7EB);
  color: var(--bf-text, #242424);
  outline: none;
}
.bfusion-insight-strip:hover .bfusion-insight-strip__label,
.bfusion-insight-strip:focus .bfusion-insight-strip__label {
  color: var(--bf-muted, #667079);
}
.bfusion-insight-strip:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: -2px;
}
/* In-visual tooltip card (src/tooltip.ts) — the host tooltip service is
   deliberately not used, so this is the same card the sibling visuals draw. */
.bfusion-tooltip {
  position: absolute;
  z-index: 999;
  max-width: 260px;
  padding: 8px 12px;
  pointer-events: none;
  background: color-mix(in srgb, var(--bf-tile, #fff) 97%, transparent);
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-radius: 6px;
  box-shadow: 0 3px 12px rgba(0, 0, 0, 0.12);
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  font-size: 11px;
  line-height: 1.5;
  color: var(--bf-text, #242424);
  /* Band swatch — the heatmap's rh-tooltip__dot. Set by the builders
       through the standard VisualTooltipDataItem.color field. */
}
.bfusion-tooltip__head {
  font-weight: 600;
  border-bottom: 1px solid var(--bf-rule, #E5E7EB);
  padding-bottom: 3px;
  margin-bottom: 4px;
}
.bfusion-tooltip__row {
  display: flex;
  justify-content: space-between;
  gap: 12px;
}
.bfusion-tooltip__label {
  color: var(--bf-muted, #667079);
  display: inline-flex;
  align-items: center;
  gap: 5px;
  white-space: nowrap;
}
.bfusion-tooltip__value {
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.bfusion-tooltip__dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  display: inline-block;
  flex: 0 0 auto;
}
/* Selected-row trend, lifted into the insights panel. */
.fte-insights-trend {
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-radius: 6px;
  background: var(--bf-tile, #FFFFFF);
  padding: 8px 10px;
  margin-bottom: 8px;
}
.fte-insights-trend-title {
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--bf-muted, #667079);
  margin-bottom: 4px;
}
.fte-trendchart {
  display: block;
  width: 100%;
  height: auto;
  overflow: visible;
}
.fte-trendchart-axis {
  display: flex;
  justify-content: space-between;
  margin-top: 2px;
  font-size: 9px;
  color: var(--bf-muted, #667079);
}
.fte-trendchart-facts {
  display: flex;
  flex-wrap: wrap;
  gap: 3px 10px;
  margin-top: 7px;
  padding-top: 7px;
  border-top: 1px solid var(--bf-surface-alt, #F4F5F7);
  font-size: 10px;
  color: var(--bf-muted, #667079);
}
.fte-trendchart-facts strong {
  color: var(--bf-strong, #1F2A44);
  font-weight: 650;
  font-variant-numeric: tabular-nums;
}
.fte-trendchart-facts-label {
  color: var(--bf-muted, #667079);
}
/* ========================================================================== */
/* License Badge & Watermark                                                   */
/* ========================================================================== */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
}
.bfusion-license-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  pointer-events: auto;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge--valid {
  background: transparent;
  border: none;
  color: var(--bf-muted, #667079);
}
.bfusion-license-badge--invalid {
  background: rgba(220, 38, 38, 0.06);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: #DC2626;
}
.bfusion-license-badge__icon {
  font-size: 11px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
